def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    fig = g != bg
    # inner colour: non-background colour with smallest bounding box area
    best = None
    for c in np.unique(g[fig]):
        ys, xs = np.nonzero(g == c)
        area = (ys.max() - ys.min() + 1) * (xs.max() - xs.min() + 1)
        if best is None or area < best[0]:
            best = (area, c)
    col = int(best[1])

    def isfig(y, x):
        return 0 <= y < H and 0 <= x < W and fig[y, x]

    out = g.copy()
    for y in range(H):
        for x in range(W):
            if fig[y, x]:
                continue
            orth = any(isfig(y + dy, x + dx) for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)))
            diag = any(isfig(y + dy, x + dx) for dy, dx in ((1, 1), (1, -1), (-1, 1), (-1, -1)))
            if diag and not orth:
                out[y, x] = col
    emit(out, f"Fill every background cell that touches the figure only diagonally with the inner colour {col}.")
    return out
